// ============================================================
// FSMGuard Patch - Guard Insertion
// CWE: CWE-1245
// Parameter: privilege_check
// Strictness: strict
// ============================================================
// This patch enforces access control before entering ADMIN
// Added by FSMGuard Stage 08 based on RL agent decision




// Strict mode: Fallback to IDLE with alert if insufficient privilege
always @(posedge clk) begin
    if (state == ADMIN) begin

        if (privilege_level != 2'b11) begin

            // alert_signal = 1'b1;  // Optional: add alert output to module
            state <= IDLE;
        end
    end
end




// ============================================================
// End FSMGuard Patch
// ============================================================
// ==== FSMGuard Patch End ====

endmodule
